class Spell {
  constructor(name) {
    this.name = name;
  }

  cast() {
    return `${this.name} is cast! (Generic effect)`;
  }
}

class FireballSpell extends Spell {
  constructor(damage) {
    super("Fireball");
    this.damage = damage;
  }

  cast() {
    return `A blazing Fireball erupts, dealing ${this.damage} damage!`;
  }
}

class HealSpell extends Spell {
  constructor(healingAmount) {
    super("Heal");
    this.healingAmount = healingAmount;
  }

  cast() {
    return `A gentle light emanates, restoring ${this.healingAmount} health!`;
  }
}

